<?php
declare(strict_types=1);
$base=getenv('TEST_DB_NAME')?:'webshop_test';if(!preg_match('/^webshop_test(?:_[a-z0-9]+)?$/D',$base))exit('Only disposable databases');
$db=new PDO('mysql:host='.(getenv('TEST_DB_HOST')?:'127.0.0.1').';port='.(getenv('TEST_DB_PORT')?:'33317').';charset=utf8mb4',getenv('TEST_DB_USER')?:'root',getenv('TEST_DB_PASSWORD')?:'local_test_only',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$db->exec('CREATE DATABASE '.$base.'_usernames CHARACTER SET utf8mb4');$db->exec('USE '.$base.'_usernames');
// Exercise the real upgrade from 1.7, with no username columns present.
$sql=file_get_contents(dirname(__DIR__).'/database/install-alpha-demo.sql');$sql=substr($sql,0,strpos($sql,'-- Alpha 1.8.'));foreach(explode(';',$sql) as $statement)if(trim($statement)!=='')$db->exec($statement);
require dirname(__DIR__).'/app/services.php';function check(bool $ok,string $label):void{if(!$ok)throw new RuntimeException($label);echo "PASS: $label\n";}
$hash=password_hash('Existing-Password-123',PASSWORD_DEFAULT);query('INSERT INTO users(role_id,name,email,password_hash) VALUES(1,?,?,?)',['Existing administrator','old-admin@example.test',$hash]);query("INSERT INTO business_partners(company,contact_name,email,phone,address,city,password_hash) VALUES('Existing company','Contact','old-partner@example.test','123','Address','City',?)",[$hash]);
$upgrade=file_get_contents(dirname(__DIR__).'/database/migrations/014_usernames.sql');foreach(explode(';',$upgrade) as $statement)if(trim($statement)!=='')$db->exec($statement);
$u=query('SELECT * FROM users WHERE id=1')->fetch();$p=query('SELECT * FROM business_partners WHERE id=1')->fetch();check($u['username']==='admin1'&&$p['username']==='saradnik1','legacy accounts receive deterministic usernames');check($u['password_hash']===$hash&&$p['password_hash']===$hash&&$u['email']==='old-admin@example.test'&&$p['email']==='old-partner@example.test','upgrade preserves passwords and contact emails');
check(normalizeUsername('  TEST.Radionica_2-3  ')==='test.radionica_2-3','username normalized independent of case');foreach(['test@example.test','ab','space name','<script>','test/../admin',str_repeat('x',65),['test']] as $bad){$rejected=false;try{normalizeUsername($bad);}catch(RuntimeException){$rejected=true;}check($rejected,'invalid username rejected');}
query("UPDATE users SET username='my.admin' WHERE id=1");query("UPDATE business_partners SET username='my.partner' WHERE id=1");foreach(explode(';',$upgrade) as $statement)if(trim($statement)!=='')$db->exec($statement);check(query('SELECT username FROM users WHERE id=1')->fetchColumn()==='my.admin'&&query('SELECT username FROM business_partners WHERE id=1')->fetchColumn()==='my.partner','repeated migration preserves edited usernames');
foreach(['users','business_partners'] as $table){$index=query('SHOW INDEX FROM '.$table.' WHERE Column_name=?',['username'])->fetchAll();check(count($index)===1&&(int)$index[0]['Non_unique']===0,'username has a unique index in '.$table);}
echo "PASS: safe username migration, repeatability, validation and unchanged account credentials.\n";
